const $=s=>document.querySelector(s),fmt=n=>new Intl.NumberFormat('ru-RU').format(n),rank=r=>({11:'J',12:'Q',13:'K',14:'A'}[r]||r);let game=new Poker.Game(),timer=null,sound=false,audio=null,thinking=false;let betValue=40;
let learning=true,coachPaused=false,lessonSeen=new Set(),actionFeedback='';
try{learning=localStorage.getItem('velvet-learning')!=='off';}catch{}
function renderCoach(){
 const g=game,p=g.players[0],active=!g.done&&g.turn===0,stage=g.done?4:g.street;
 document.body.classList.toggle('learning',learning);$('#coach').hidden=!learning;$('#action-help').hidden=!learning||g.done;
 $('#learning-toggle').setAttribute('aria-checked',String(learning));$('#learning-toggle').innerHTML=(learning?'Обучение включено':'Включить обучение')+' <i></i>';
 if(!learning)return;
 document.querySelectorAll('.lesson-progress li').forEach((el,i)=>{el.classList.toggle('current',i===stage);el.classList.toggle('complete',i<stage);if(i===stage)el.setAttribute('aria-current','step');else el.removeAttribute('aria-current');});
 const info=PokerCoach.stages[g.street];$('#coach-title').textContent=g.done?'Почему раздача закончилась':info[0];$('#coach-explanation').textContent=g.done?PokerCoach.outcome(g):info[2];$('#coach-note').textContent=g.done?'Следующая раздача начнётся только по вашей кнопке.':info[3];
 $('#coach-continue').hidden=!coachPaused;$('#coach-hand-title').textContent=g.board.length>=3?'Ваши лучшие пять карт':'Ваши две закрытые карты';const cards=[...p.cards,...g.board];$('#coach-best').innerHTML=(cards.length>=5?PokerCoach.bestFive(cards):p.cards).map(c=>card(c)).join('');const shared=[...new Set(g.board.filter(c=>g.board.filter(q=>q.r===c.r).length>1).map(c=>rank(c.r)))];$('#coach-hand-description').textContent=PokerCoach.describe(cards)+(shared.length?' На столе повторяются '+shared.join(', ')+': эти общие карты есть и у соперников.':'')+(p.folded?' Вы уже сделали пас: эта рука не участвует в сравнении.':'');
 const advice=active&&!coachPaused?PokerCoach.advice(g):null;$('#coach-advice').textContent=coachPaused?'Пауза для объяснения. Прочитайте подсказку и нажмите «Понятно, продолжить».':advice?advice.title+'. '+advice.text:g.done?'Разберите результат выше или посмотрите таблицу комбинаций.':'Сейчас ход соперников. Подсказка к вашему решению появится, когда очередь дойдёт до вас.';
 ['fold','call','raise'].forEach(id=>{$('#'+id).classList.toggle('suggested',!!advice&&advice.type===id);if(coachPaused)$('#'+id).disabled=true;});
 if(coachPaused){$('#bet-range').disabled=true;document.querySelectorAll('[data-bet]').forEach(b=>b.disabled=true);$('#action-title').textContent='Пауза для обучения';$('#action-detail').textContent='Прочитайте объяснение выше';}
 const call=Math.min(Math.max(0,g.currentBet-p.bet),p.stack);$('#call-help').innerHTML=call?'<strong>Колл '+fmt(call)+'</strong> — доплатить столько фишек, чтобы продолжить.':'<strong>Чек</strong> — остаться в игре бесплатно: доплачивать сейчас не нужно.';
 $('#raise-help').innerHTML='<strong>Повысить до '+fmt(betValue)+'</strong> — сделать вашу ставку за этот круг равной '+fmt(betValue)+'. Доплата: '+fmt(Math.max(0,betValue-p.bet))+'.';
 $('#coach-feedback').hidden=!actionFeedback;$('#coach-feedback').textContent=actionFeedback;
}
function showBasics(){clearTimeout(timer);modal('<div class="eyebrow">ПОКЕР С НУЛЯ</div><h2>Давайте разберёмся вместе.</h2><p><strong>1. Посмотрите на две карты внизу.</strong> Это ваша рука. Карты в центре стола — общие, ими пользуются все.</p><p><strong>2. Соберите лучшие пять карт.</strong> Например, две дамы — это пара, а пять карт одной масти — флеш. Можно использовать 0, 1 или 2 свои карты.</p><p><strong>3. Решите, продолжать ли раздачу.</strong> Если платить не нужно — доступен чек. Если соперник поставил — можно уравнять (колл), повысить или сбросить карты (пас).</p><p><strong>4. Заберите банк.</strong> Побеждает лучшая комбинация на вскрытии или последний игрок, который не сделал пас. За столом только виртуальные фишки.</p><p>Помощник объяснит каждый этап, покажет вашу комбинацию и подскажет осторожный вариант хода. Решение всегда за вами.</p><button class="modal-action" id="begin-lesson">Понятно, к столу →</button>');$('#begin-lesson').onclick=()=>$('#modal').close();}

function tone(f=440){if(!sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();const o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.value=f;g.gain.setValueAtTime(.035,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.15);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+.15);}catch{}}
function card(c,back=false,delay=0){if(back)return '<div class="card back" aria-label="Закрытая карта"></div>';if(!c)return '<div class="card empty" aria-label="Карта ещё не открыта"></div>';return `<div class="card ${c.si===1||c.si===2?'red':''}" style="animation-delay:${delay}ms" aria-label="${rank(c.r)} ${c.s}"><span class="rank">${rank(c.r)}</span><span class="suit">${c.s}</span><span class="big-suit">${c.s}</span></div>`;}
function render(){const g=game,hero=g.players[0],myTurn=!g.done&&g.turn===0;$('#hand-number').textContent=String(g.hand).padStart(2,'0');$('#history-hand').textContent='РАЗДАЧА '+String(g.hand).padStart(2,'0');$('#pot').innerHTML=fmt(g.pot)+' <span>◉</span>';$('#board').innerHTML=Array.from({length:5},(_,i)=>card(g.board[i])).join('');$('#street').textContent=g.done?'РАЗДАЧА ЗАВЕРШЕНА':['ПРЕФЛОП','ФЛОП','ТЁРН','РИВЕР'][g.street];$('#seats').innerHTML=g.players.map((p,i)=>`<div class="seat seat-${i} ${p.folded?'folded':''} ${g.turn===i&&!g.done?'current':''}"><div class="hole-cards">${p.cards.map(c=>card(c,i!==0&&!(g.done&&g.showdown&&!p.folded))).join('')}</div><div class="player-info"><div class="avatar">${['В','А','М','С','Л'][i]}</div><span class="player-name">${p.name}${i===0?'<em>ЭТО ВЫ</em>':''}</span><span class="player-stack">${fmt(p.stack)} <span>◉</span></span>${g.dealer===i?'<span class="dealer" title="Баттон дилера">D</span>':''}</div><div class="player-status">${g.turn===i&&!g.done?(i===0?'Ваш ход':'Думает…'):p.status}</div>${p.bet?'<div class="bet-chip">'+fmt(p.bet)+'</div>':''}</div>`).join('');$('#balance').textContent=fmt(hero.stack);const delta=hero.stack-2000;$('#profit').textContent=delta===0?'Начальный стек: 2 000':(delta>0?'+':'−')+fmt(Math.abs(delta))+' за сессию';$('#profit').classList.toggle('negative',delta<0);$('#hands-played').textContent=g.played;$('#hands-won').textContent=g.won;$('#win-rate').textContent=g.played?Math.round(g.won/g.played*100)+'%':'—';$('#history').innerHTML=g.logs.map(l=>`<div class="history-item ${l.kind}"><span class="log-icon">${l.kind==='phase'?'◇':l.kind==='win'?'♛':'·'}</span><span>${l.text.replace(/^([^·]+) · /,'<strong>$1</strong> · ')}</span></div>`).join('');$('#history').scrollTop=$('#history').scrollHeight;
$('#turn-indicator').classList.toggle('active',myTurn);$('#action-title').textContent=g.done?'Раздача завершена':myTurn?'Ваш ход':hero.folded?'Вы сбросили карты':g.players[g.turn]?.name+' принимает решение';$('#action-detail').textContent=g.done?'Готовы к следующей?':myTurn?'Выберите действие':'Следите за игрой соперников';let score=g.board.length>=3&&hero.cards.length?Poker.evaluate([...hero.cards,...g.board]):null;$('#hand-strength').textContent=hero.folded?'Пас':score?Poker.HANDS[score[0]]:hero.cards.length&&hero.cards[0].r===hero.cards[1].r?'Карманная пара':'Карманные карты';$('#play-controls').hidden=g.done;$('#next-hand').hidden=!g.done;$('#next-hand').textContent=hero.stack===0?'Начать новую сессию →':g.players.filter(p=>p.stack>0).length<2?'Вы выиграли стол! Новая сессия →':'Следующая раздача →';const l=g.legal();if(l){const min=l.min,max=l.max;betValue=Math.min(max,Math.max(min,betValue));$('#bet-range').min=min;$('#bet-range').max=max;$('#bet-range').value=betValue;$('#bet-range').step=1;$('#bet-amount').textContent=fmt(betValue);$('#raise-label').textContent=fmt(betValue);$('#call').innerHTML=l.call?'Колл '+fmt(l.callAmount)+' <small>C</small>':'Чек <small>C</small>';$('#raise').disabled=!myTurn||!l.canRaise;$('#bet-range').disabled=!myTurn||!l.canRaise;document.querySelectorAll('[data-bet]').forEach(b=>b.disabled=!myTurn||!l.canRaise);}
$('#fold').disabled=!myTurn;$('#call').disabled=!myTurn;$('#announcement').classList.toggle('visible',g.done);if(g.done){const best=g.results.filter(r=>r.amount>0);$('#announcement').textContent=best.map(r=>(r.index===0?'Вы':g.players[r.index].name)+' +'+fmt(r.amount)).join(' · ');$('#tip-text').textContent=hero.stack===0?'Фишки закончились. Начните новую сессию — каждый снова получит по 2 000.':g.results.some(r=>r.index===0)?'Хорошая раздача. Каждое решение важнее отдельного результата.':'Одна раздача — ещё не вся игра. Сохраняйте терпение и выбирайте сильные руки.';save();}renderCoach();}
function tick(){clearTimeout(timer);const lessonKey=game.hand+':'+game.street;if(learning&&!game.done&&!lessonSeen.has(lessonKey)){lessonSeen.add(lessonKey);coachPaused=true;actionFeedback='';}render();if(coachPaused||$('#modal').open)return;if(game.done){thinking=false;tone(640);return;}if(game.turn!==0){thinking=true;timer=setTimeout(()=>{const move=game.bot();game.act(...move);betValue=game.currentBet+game.minRaise;tone(260);tick();},850+Math.random()*500);}else{thinking=false;tone(510);}}
function act(type){if(game.turn!==0||game.done||coachPaused||$('#modal').open)return;const before=game.legal(),amount=Number($('#bet-range').value),paid=game.players[0].bet;if(game.act(type,amount)){actionFeedback=type==='fold'?'Вы сделали пас. Больше платить в этой раздаче не нужно; уже поставленные фишки остаются в банке. Теперь можно наблюдать за соперниками.':type==='raise'?'Вы повысили ставку до '+fmt(amount)+' за этот круг, доплатив '+fmt(amount-paid)+'. Соперникам нужно уравнять её, повысить снова или сделать пас.':before.call?'Вы сделали колл: добавили '+fmt(before.callAmount)+' фишек. Это сохраняет участие в раздаче, но ещё не означает победу.':'Вы сделали чек: ничего не заплатили и остались в раздаче. Если кто-то повысит ставку, вам снова нужно будет принять решение.';betValue=game.currentBet+game.minRaise;tick();}}
function start(){clearTimeout(timer);coachPaused=false;actionFeedback='';lessonSeen.clear();game.start();betValue=40;tick();}
function save(){try{localStorage.setItem('velvet-session',JSON.stringify({stacks:game.players.map(p=>p.stack),dealer:game.dealer,hand:game.hand,played:game.played,won:game.won}));}catch{}}
function reset(){clearTimeout(timer);game=new Poker.Game();try{localStorage.removeItem('velvet-session');}catch{}$('#modal').close();start();}
function modal(html){clearTimeout(timer);$('#modal-content').innerHTML=html;$('#modal').showModal();}
$('#fold').onclick=()=>act('fold');$('#call').onclick=()=>act('call');$('#raise').onclick=()=>act('raise');$('#bet-range').oninput=e=>{betValue=+e.target.value;$('#bet-amount').textContent=fmt(betValue);$('#raise-label').textContent=fmt(betValue);renderCoach();};document.querySelectorAll('[data-bet]').forEach(b=>b.onclick=()=>{const l=game.legal();if(!l)return;let v={min:l.min,half:game.currentBet+Math.round(game.pot/2),pot:game.currentBet+game.pot,all:l.max}[b.dataset.bet];betValue=Math.max(l.min,Math.min(l.max,v));$('#bet-range').value=betValue;$('#bet-range').dispatchEvent(new Event('input'));});
$('#next-hand').onclick=()=>{if(!game.players[0].stack||game.players.filter(p=>p.stack>0).length<2)reset();else start();};$('#restart').onclick=()=>{modal('<div class="eyebrow">НОВЫЙ СТАРТ</div><h2>С чистого листа?</h2><p>Текущая игра и статистика сессии будут сброшены. Каждый игрок получит 2 000 виртуальных фишек.</p><button class="modal-action" id="confirm-reset">Начать новую сессию</button>');$('#confirm-reset').onclick=reset;};$('#sound').onclick=()=>{sound=!sound;$('#sound').classList.toggle('on',sound);$('#sound').title=sound?'Выключить звук':'Включить звук';$('#sound').setAttribute('aria-label',$('#sound').title);tone();};$('#rules').onclick=()=>modal('<div class="eyebrow">ТЕХАССКИЙ ХОЛДЕМ</div><h2>Игра начинается с двух карт.</h2><p>Соберите лучшую комбинацию из пяти карт, используя свои две карты и пять общих в любом сочетании. Или заставьте всех соперников сбросить карты.</p><ul><li>Каждый начинает с 2 000 фишек. Блайнды — 10 / 20.</li><li><strong>Префлоп:</strong> вы получаете две закрытые карты.</li><li><strong>Флоп, тёрн, ривер:</strong> на стол выходят три карты, затем ещё по одной. После каждого этапа — круг ставок.</li><li><strong>Пас:</strong> выйти из раздачи. <strong>Чек:</strong> пропустить ставку, если доплачивать не нужно. <strong>Колл:</strong> уравнять. <strong>Рейз:</strong> повысить общую ставку до выбранного числа.</li><li>На вскрытии сильнейшая рука забирает банк. Равные руки делят его; при олл-ине создаются побочные банки.</li></ul><p>Игра идёт против четырёх ботов на виртуальные фишки. Завершённые раздачи сохраняются в этом браузере.</p>');$('#combinations').onclick=()=>modal('<div class="eyebrow">ОТ СИЛЬНЕЙШЕЙ К СЛАБЕЙШЕЙ</div><h2>Комбинации</h2>'+[['Роял-флеш','10 J Q K A ♠'],['Стрит-флеш','5 6 7 8 9 ♣'],['Каре','K K K K 2'],['Фулл-хаус','Q Q Q 7 7'],['Флеш','A J 9 6 2 ♥'],['Стрит','4 5 6 7 8'],['Сет','8 8 8 K 3'],['Две пары','J J 5 5 A'],['Пара','10 10 A 6 2'],['Старшая карта','A J 8 4 2']].map(([a,b])=>'<div class="combo-row"><span>'+a+'</span><span>'+b+'</span></div>').join('')+'<p>Роял-флеш — старший стрит-флеш. При равных комбинациях сравниваются ранги карт и кикеры.</p>');$('#profile').onclick=()=>modal('<div class="eyebrow">ВАША СЕССИЯ</div><h2>За столом — вы.</h2><p>Стек: <strong>'+fmt(game.players[0].stack)+'</strong> фишек<br>Завершено раздач: <strong>'+game.played+'</strong><br>Прибыльных раздач: <strong>'+game.won+'</strong></p><p>Прогресс сохраняется после завершения каждой раздачи. Во время незавершённой раздачи перезагрузка вернёт вас к последнему сохранению.</p>');$('#close-modal').onclick=()=>$('#modal').close();$('#modal').onclick=e=>{if(e.target===$('#modal')){let r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}};document.addEventListener('keydown',e=>{if($('#modal').open||e.ctrlKey||e.metaKey||e.altKey||e.repeat||['INPUT','BUTTON'].includes(document.activeElement.tagName))return;const k=e.key.toLowerCase();if(k==='f'||k==='а')act('fold');if(k==='c'||k==='с')act('call');if(k==='r'||k==='к')act('raise');});
$('#learning-toggle').onclick=()=>{learning=!learning;coachPaused=false;try{localStorage.setItem('velvet-learning',learning?'on':'off');}catch{}if(learning)lessonSeen.delete(game.hand+':'+game.street);tick();};
$('#coach-continue').onclick=()=>{coachPaused=false;tick();};$('#lesson-basics').onclick=showBasics;$('#coach-combinations').onclick=()=>$('#combinations').click();
$('#modal').addEventListener('close',()=>tick());
try{let s=JSON.parse(localStorage.getItem('velvet-session'));if(s&&Array.isArray(s.stacks)&&s.stacks.length===5&&s.stacks.every(n=>Number.isInteger(n)&&n>=0)&&s.stacks.reduce((a,b)=>a+b,0)===10000){s.stacks.forEach((n,i)=>game.players[i].stack=n);game.dealer=Number.isInteger(s.dealer)?s.dealer:4;game.hand=s.hand||0;game.played=s.played||0;game.won=s.won||0;if(!s.stacks[0]||s.stacks.filter(n=>n>0).length<2)game=new Poker.Game();}}catch{}start();
